  void prepareInvoice(){var proposal=propose();assertEquals("APPLIED",proposal.get("outcome"),proposal.toString());var order=dispatch(proposal,approve(proposal,"APPROVE"));assertEquals("APPLIED",order.get("outcome"),order.toString());line=order.get("poLineId").toString();ref=id();source=row("sourceNamespace","native-fixture","sourceKey",id(),"sourceVersion","1","lineId",line,"referenceId",ref,"scopeKind","PURCHASE","invoiceKind","COMMERCIAL","itemId",item,"quantity","100","unit","BOX","unitPrice","1","originalAmount","100","currency","EUR","occurredAt",AS_OF.toString(),"fxSnapshot",row("pair","EUR/KRW","rate","1500","date","2026-10-07","source","synthetic-fx","policyVersion","fx-v1","rounding","HALF_UP_SCALE_0"));String doc=attach(source,"PURCHASE_ORDER_LINE",line);invoiceSlots=row("invoiceKind","COMMERCIAL","originalAmount",row("value","100","currency","EUR"),"line",row("purchaseLineId",line,"receiptOccurrenceId",ref,"quantity",row("value","100","unit","BOX"),"unitPrice",row("value","1","currency","EUR")),"scopeKind","PURCHASE","evidence",doc,"fxSnapshot",source.get("fxSnapshot"));}
  String attach(Map<String,Object> original,String kind,String subject){try{byte[] data=json.writeValueAsBytes(original);return runtime.requestContext().run(c->{return records.attachDocument(new com.mulino.application.evidence.EvidenceRecords.DocumentInput(new com.mulino.domain.evidence.EvidenceTypes.Subject(com.mulino.domain.evidence.EvidenceTypes.SubjectKind.valueOf(kind),subject),"native-fixture",id(),"application/json",com.mulino.adapters.blob.LocalBlobStore.hash(data),"synthetic-original",null),data);}).get("id").toString();}catch(Exception e){throw new IllegalStateException(e);}}
  Map<String,Object> settlement(String op,int rev,Map<String,Object> slots,String key){return runtime.requestContext().run(c->{return commands.execute(row("intentKind",op.equals("matchInvoice")||op.equals("confirmReceipt")?"COMMAND":"RECORD","capabilityId",op,"definitionVersion","1.0.0","expectedRevision",rev,"slots",slots,"provenance",Map.of(),"subjectRefs",List.of(),"commandIdempotencyKey",key));});}
  Map<String,Object> canonical(String iid,String kind,Map<String,Object> original,String quantity,String unit){String doc=attach(original,"INVOICE",iid);String eventKey=id();return runtime.requestContext().run(c->{var subject=new com.mulino.domain.evidence.EvidenceTypes.Subject(com.mulino.domain.evidence.EvidenceTypes.SubjectKind.INVOICE,iid);var event=records.recordActivity(new com.mulino.application.evidence.EvidenceRecords.EventInput(subject,kind,"native-fixture",eventKey,"1",new com.mulino.domain.evidence.EvidenceTypes.EffectiveTime(AS_OF,null,"Asia/Seoul","SECOND"),com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,write(original),null,null));var claim=records.recordClaim(new com.mulino.application.evidence.EvidenceRecords.ClaimInput(event.get("id").toString(),doc,"source-reference",quantity,unit,com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,null));var review=reconciliation.match(context(),new com.mulino.application.evidence.EvidenceReconciliation.Review(claim.get("id").toString(),doc,iid,null,"fixture-v1","native-fixture:"+eventKey+":1",quantity,unit,AS_OF,"exact original source"),"matchSourceIdentity");assertEquals("MATCHED",review.get("outcome"),review.toString());var fact=reconciliation.link(context(),review.get("id").toString());return row("documentId",doc,"occurrenceId",fact.get("id"));});}
  String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
  @Test void invoiceGatewayPreservesFxAndClaimHasNoConfirmedEffect(){prepareInvoice();String key=id();int stock=count("mulino_inventory_QuantitySegments");var a=settlement("recordInvoice",1,invoiceSlots,key);assertEquals("APPLIED",a.get("outcome"),a.toString());assertEquals("150000",a.get("convertedAmount"));assertEquals(a,settlement("recordInvoice",1,invoiceSlots,key));assertEquals(1,count("mulino_trade_settlement_Invoices"));assertEquals("CONFLICT",settlement("recordInvoice",1,invoiceSlots,id()).get("outcome"));assertEquals(0,count("mulino_trade_settlement_Matches"));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM mulino_trade_purchase_ExecutionEffects WHERE organizationId=? AND kind='INVOICED'",Integer.class,org));assertEquals(stock,count("mulino_inventory_QuantitySegments"));assertThrows(Exception.class,()->jdbc.update("UPDATE mulino_trade_settlement_Invoices SET fxRate=1600 WHERE organizationId=?",org));invoiceSlots.put("originalAmount",row("value","101","currency","EUR"));assertEquals("CONFLICT",settlement("recordInvoice",1,invoiceSlots,key).get("outcome"));}
  @Test void staleUnauthorizedHaveZeroInvoiceEffects(){prepareInvoice();assertEquals("CONFLICT",settlement("recordInvoice",0,invoiceSlots,id()).get("outcome"));jdbc.update("UPDATE mulino_identity_CapabilityAssignments SET revokedAt=CURRENT_TIMESTAMP WHERE organizationId=? AND capabilityId='recordInvoice'",org);assertEquals("REJECTED",settlement("recordInvoice",1,invoiceSlots,id()).get("outcome"));assertEquals(0,count("mulino_trade_settlement_Invoices"));}
  @Test void canonicalSourcePathAndPaymentReferenceHaveNoBankOrPaymentApproval(){prepareInvoice();var invoice=settlement("recordInvoice",1,invoiceSlots,id());String iid=invoice.get("invoiceId").toString();var canonical=canonical(iid,"INVOICE",source,"100","BOX");var noReceipt=settlement("matchInvoice",1,row("invoiceId",iid,"canonicalOccurrenceId",canonical.get("occurrenceId"),"evidence",canonical.get("documentId")),id());assertEquals("REJECTED",noReceipt.get("outcome"));assertEquals(0,count("mulino_trade_settlement_Matches"));Map<String,Object> payment=row("invoiceId",iid,"amount","100","currency","EUR","externalPaymentReference",id(),"observedAt",AS_OF.toString(),"occurredAt",AS_OF.toString(),"externalEventId",id());var proof=canonical(iid,"PAYMENT_REFERENCE",payment,null,null);var slots=row("invoiceId",iid,"amount",row("value","100","currency","EUR"),"externalPaymentReference",payment.get("externalPaymentReference"),"observedAt",AS_OF.toString(),"evidence",proof.get("documentId"),"canonicalOccurrenceId",proof.get("occurrenceId"));var result=settlement("recordPaymentReference",1,slots,id());assertEquals("APPLIED",result.get("outcome"),result.toString());assertEquals(false,result.get("paymentAuthorized"));assertEquals("0",result.get("bankEffect"));assertEquals(0,jdbc.queryForObject("SELECT sum(bankEffect) FROM mulino_trade_settlement_PaymentReferences WHERE organizationId=?",java.math.BigDecimal.class,org).signum());assertEquals(1,count("mulino_runtime_Outbox"));}
  @Test void mismatchedCanonicalDocumentCannotRecordDifferentPayment(){prepareInvoice();String iid=settlement("recordInvoice",1,invoiceSlots,id()).get("invoiceId").toString();Map<String,Object> original=row("invoiceId",iid,"amount","100","currency","EUR","externalPaymentReference",id(),"observedAt",AS_OF.toString(),"occurredAt",AS_OF.toString(),"externalEventId",id());var proof=canonical(iid,"PAYMENT_REFERENCE",original,null,null);var altered=new LinkedHashMap<>(original);altered.put("amount","999");String badDoc=attach(altered,"INVOICE",iid);var result=settlement("recordPaymentReference",1,row("invoiceId",iid,"amount",row("value","999","currency","EUR"),"externalPaymentReference",original.get("externalPaymentReference"),"observedAt",AS_OF.toString(),"evidence",badDoc,"canonicalOccurrenceId",proof.get("occurrenceId")),id());assertEquals("HELD",result.get("outcome"),result.toString());assertEquals(0,count("mulino_trade_settlement_PaymentReferences"));}
  @Test void invoiceAuditFailureRollsBackInvoiceIdempotencyAndEffects(){prepareInvoice();int before=count("mulino_commands_CommandRecords"),stock=count("mulino_inventory_QuantitySegments");String function="settlement_audit_"+org.replace("-","");String trigger=function+"_trigger";jdbc.execute("CREATE FUNCTION "+function+"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.organizationId='"+org+"' AND NEW.capabilityId='recordInvoice' THEN RAISE EXCEPTION 'test audit failure'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER "+trigger+" BEFORE INSERT ON mulino_commands_CommandAudits FOR EACH ROW EXECUTE FUNCTION "+function+"()");try{assertThrows(Exception.class,()->settlement("recordInvoice",1,invoiceSlots,id()));assertEquals(0,count("mulino_trade_settlement_Invoices"));assertEquals(before,count("mulino_commands_CommandRecords"));assertEquals(stock,count("mulino_inventory_QuantitySegments"));}finally{jdbc.execute("DROP TRIGGER "+trigger+" ON mulino_commands_CommandAudits");jdbc.execute("DROP FUNCTION "+function+"()");}}
  void realReceipt(){String range=id();Map<String,Object> original=row("rangeRootId",range,"startQuantity","0","quantity","100","unit","BOX","itemId",item,"lotId",lot,"placeId",place,"workId",work,"occurredAt",AS_OF.toString());String doc=attach(original,"WORK",work);var fact=runtime.requestContext().run(c->{var event=records.recordActivity(new com.mulino.application.evidence.EvidenceRecords.EventInput(new com.mulino.domain.evidence.EvidenceTypes.Subject(com.mulino.domain.evidence.EvidenceTypes.SubjectKind.WORK,work),"PHYSICAL_RECEIPT","native-fixture",id(),"1",new com.mulino.domain.evidence.EvidenceTypes.EffectiveTime(AS_OF,null,"Asia/Seoul","SECOND"),com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,write(original),null,null));var provisional=settlement("receiveProvisional",0,row("eventId",event.get("id"),"rangeRootId",range,"startQuantity","0","quantity","100","unit","BOX","itemId",item,"lotId",lot,"placeId",place,"workId",work,"purchaseLineId",line,"ownerId",actor,"supervisorId",actor,"nextAction","대조한다","nextCheckAt",Instant.now().plusSeconds(3600).toString(),"occurredAt",AS_OF.toString()),id());assertEquals("APPLIED",provisional.get("outcome"),provisional.toString());var claim=records.recordClaim(new com.mulino.application.evidence.EvidenceRecords.ClaimInput(event.get("id").toString(),doc,"actual receipt","100","BOX",com.mulino.domain.evidence.EvidenceTypes.ValueState.KNOWN,null));String eventKey=jdbc.queryForObject("SELECT externalEventId FROM mulino_evidence_Events WHERE ID=?",String.class,event.get("id"));var review=reconciliation.match(context(),new com.mulino.application.evidence.EvidenceReconciliation.Review(claim.get("id").toString(),doc,range,null,"fixture-v1","native-fixture:"+eventKey+":1","100","BOX",AS_OF,"real receipt"),"matchSourceIdentity");assertEquals("MATCHED",review.get("outcome"),review.toString());var canonical=reconciliation.link(context(),review.get("id").toString());var confirm=settlement("confirmReceipt",0,row("receiptId",((Map<?,?>)provisional.get("effects")).get("receiptId"),"lotId",lot,"canonicalOccurrenceId",canonical.get("id")),id());assertEquals("APPLIED",confirm.get("outcome"),confirm.toString());return canonical;});ref=fact.get("id").toString();source.put("referenceId",ref);source.put("unitPrice","1.05");source.put("originalAmount","105");source.remove("fxSnapshot");invoiceSlots.put("evidence",attach(source,"PURCHASE_ORDER_LINE",line));invoiceSlots.remove("fxSnapshot");invoiceSlots.put("originalAmount",row("value","105","currency","EUR"));invoiceSlots.put("line",row("purchaseLineId",line,"receiptOccurrenceId",ref,"quantity",row("value","100","unit","BOX"),"unitPrice",row("value","1.05","currency","EUR")));}
  @Test void exactManagerConfirmationRetainsOriginalVarianceAndDuty(){prepareInvoice();realReceipt();String iid=settlement("recordInvoice",1,invoiceSlots,id()).get("invoiceId").toString();var fact=canonical(iid,"INVOICE",source,"100","BOX");var match=settlement("matchInvoice",1,row("invoiceId",iid,"canonicalOccurrenceId",fact.get("occurrenceId"),"evidence",fact.get("documentId")),id());assertEquals("APPLIED",match.get("outcome"),match.toString());assertEquals("5.000000000000",match.get("originalDifference"));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM mulino_work_read_ObligationReferences WHERE organizationId=? AND kind='SETTLEMENT_DIFFERENCE' AND status='OPEN'",Integer.class,org));var original=row("invoiceId",iid,"mode","PROPOSE","amount","5","currency","EUR","reason","원 차이를 확인한다","occurredAt",AS_OF.toString(),"externalEventId",id());var proof=canonical(iid,"SETTLEMENT_ADJUSTMENT",original,null,null);var slots=row("invoiceId",iid,"mode","PROPOSE","amount",row("value","5","currency","EUR"),"reason","원 차이를 확인한다","evidence",proof.get("documentId"),"canonicalOccurrenceId",proof.get("occurrenceId"));var proposed=settlement("recordSettlementAdjustment",1,slots,id());assertEquals("APPLIED",proposed.get("outcome"),proposed.toString());original.put("mode","CONFIRM");original.put("proposalId",proposed.get("adjustmentId"));original.put("proposalHash",proposed.get("proposalHash"));original.put("policyVersion","command-fixture-v1");original.put("externalEventId",id());proof=canonical(iid,"SETTLEMENT_ADJUSTMENT",original,null,null);slots.putAll(row("mode","CONFIRM","proposalId",proposed.get("adjustmentId"),"proposalHash",proposed.get("proposalHash"),"policyVersion","command-fixture-v1","evidence",proof.get("documentId"),"canonicalOccurrenceId",proof.get("occurrenceId")));assertEquals("REJECTED",settlement("recordSettlementAdjustment",1,slots,id()).get("outcome"));insert("mulino_identity_ManagementAuthorities",row("organizationId",org,"ID",id(),"actorId",actor,"capabilityId","recordSettlementAdjustment","scopeKind","ORGANIZATION","scopeId",org,"validFrom",Timestamp.from(Instant.now().minusSeconds(3600)),"validUntil",Timestamp.from(Instant.now().plusSeconds(3600))));var confirmed=settlement("recordSettlementAdjustment",1,slots,id());assertEquals("APPLIED",confirmed.get("outcome"),confirmed.toString());assertEquals(0,new java.math.BigDecimal(confirmed.get("settlementDifference").toString()).signum());assertEquals(0,jdbc.queryForObject("SELECT originalDifference FROM mulino_trade_settlement_Matches WHERE organizationId=?",java.math.BigDecimal.class,org).compareTo(new java.math.BigDecimal("5")));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM mulino_work_read_ObligationReferences WHERE organizationId=? AND kind='SETTLEMENT_DIFFERENCE' AND status='OPEN'",Integer.class,org));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM mulino_trade_settlement_Adjustments WHERE organizationId=? AND status='CONFIRMED'",Integer.class,org));assertEquals(0,count("mulino_trade_settlement_PaymentReferences"));}
